exploreUrl:
@js:
var result=[];
var obMap={"综合":"-1","点击":"click","更新":"update","字数":"wordcount","发布":"public"};
var finMap={"全部":"-1","连载中":"0","已完结":"1"};
var updMap={"全部":"-1","三日内":"3","七日内":"7","半月内":"15","一月内":"30","三月内":"90"};
var sizeMap={"全部":"-1","30万以下":"30","30~50万":"50","50~100万":"100","100~200万":"200","200万以上":"999"};
result.push({title:"排序方式",type:"select",chars:Object.keys(obMap),default:infoMap["排序方式"]||"综合",action:"java.refreshExplore()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.45}});
result.push({title:"写作进度",type:"select",chars:Object.keys(finMap),default:infoMap["写作进度"]||"全部",action:"java.refreshExplore()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.45}});
result.push({title:"作品字数",type:"select",chars:Object.keys(sizeMap),default:infoMap["作品字数"]||"全部",action:"java.refreshExplore()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.45,layout_wrapBefore:true}});
result.push({title:"更新时间",type:"select",chars:Object.keys(updMap),default:infoMap["更新时间"]||"全部",action:"java.refreshExplore()",style:{layout_flexGrow:1,layout_flexBasisPercent:0.45}});
var ob=obMap[infoMap["排序方式"]||"综合"];
var fin=finMap[infoMap["写作进度"]||"全部"];
var sz=sizeMap[infoMap["作品字数"]||"全部"];
var upd=updMap[infoMap["更新时间"]||"全部"];
function mk(catId){return "https://www.aabook.xyz/category.html?pageNum={{page}}&pageSize=30&catId="+catId+"&size="+sz+"&isFinish="+fin+"&updT="+upd+"&orderBy="+ob;}
var cats=[["全部","-1"],["穿越","chuanyue"],["异能","yineng"],["言情","yanqing"],["玄幻","xuanhuan"],["校园","xiaoyuan"],["仙侠","xianxia"],["武侠","wuxia"],["都市","dushi"],["历史","lishi"],["古典","gudian"],["惊悚","jingsong"],["耽美","danmei"],["同人","tongren"],["女尊","nvzun"],["网游","wangyou"],["乡土","xiangtu"],["官场","guanchang"],["职场","zhichang"],["单篇","danpian"]];
cats.forEach(function(c){result.push({title:c[0],url:mk(c[1]),style:{layout_flexGrow:1,layout_flexBasisPercent:0.2}});});
result.push({title:"📊 榜单",url:"",style:{layout_flexGrow:1,layout_flexBasisPercent:1}});
result.push({title:"🔥 点击榜",url:"https://www.aabook.xyz/ranking.php?t=click",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}});
result.push({title:"📚 新书榜",url:"https://www.aabook.xyz/ranking.php?t=newbook",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}});
result.push({title:"📝 字数榜",url:"https://www.aabook.xyz/ranking.php?t=totalword",style:{layout_flexGrow:1,layout_flexBasisPercent:0.25}});
result.push({title:"🔄 最近更新",url:"https://www.aabook.xyz/category.html?pageNum={{page}}&pageSize=30&catId=-1&size=-1&isFinish=-1&updT=-1&orderBy=update",style:{layout_flexGrow:1,layout_flexBasisPercent:1}});
infoMap.save();
JSON.stringify(result);

